node -e '
const { spawn } = require("child_process");
const server = spawn("npm", ["run", "start", "--", "-p", "3099"], { stdio: "inherit" });
setTimeout(async () => {
  try {
    const t0 = Date.now();
    const res1 = await fetch("http://localhost:3099/products/lamp?currency=EUR");
    const html1 = await res1.text();
    const t1 = Date.now() - t0;

    const t2Start = Date.now();
    const res2 = await fetch("http://localhost:3099/products/lamp?currency=EUR");
    const html2 = await res2.text();
    const t2 = Date.now() - t2Start;

    const res3 = await fetch("http://localhost:3099/products/lamp");
    const html3 = await res3.text();

    const res4 = await fetch("http://localhost:3099/products/vase?currency=EUR");
    const html4 = await res4.text();

    console.log("Res1 status:", res1.status, "time:", t1, "has Brass lamp:", html1.includes("Brass lamp"), "has EUR 110.40:", html1.includes("EUR 110.40"), "has Stone vase:", html1.includes("Stone vase"));
    console.log("Res2 status:", res2.status, "time:", t2, "has EUR 110.40:", html2.includes("EUR 110.40"));
    console.log("Res3 status:", res3.status, "has USD 120.00:", html3.includes("USD 120.00"));
    console.log("Res4 status:", res4.status, "has Stone vase:", html4.includes("Stone vase"), "has EUR 73.60:", html4.includes("EUR 73.60"), "has Brass lamp:", html4.includes("Brass lamp"));
  } finally {
    server.kill();
    process.exit(0);
  }
}, 2000);
'
